use super::*;

/// The verbatim text of every `import_statement` in `code`, via tree-sitter (so comments and strings
/// that merely contain the word "import" are never mistaken for one).
pub(crate) fn import_statements(code: &str) -> Vec<String> {
    let mut parser = Parser::new();
    if parser
        .set_language(&tree_sitter_typescript::LANGUAGE_TYPESCRIPT.into())
        .is_err()
    {
        return Vec::new();
    }
    let Some(tree) = parser.parse(code, None) else {
        return Vec::new();
    };
    let bytes = code.as_bytes();
    let mut out = Vec::new();
    let mut stack = vec![tree.root_node()];
    while let Some(node) = stack.pop() {
        if node.kind() == "import_statement" {
            if let Ok(text) = node.utf8_text(bytes) {
                out.push(text.to_string());
            }
            // An import cannot contain another import; no need to descend.
            continue;
        }
        for i in (0..node.child_count() as u32).rev() {
            if let Some(child) = node.child(i) {
                stack.push(child);
            }
        }
    }
    out
}
